mapper.select:
SELECT om.id, om.order_no AS orderNo, om.shop_id AS shopId, s.shop_name AS shopName, om.customer_id AS customerId, c.name AS customerName, om.total_qty AS totalQty, om.total_amount AS totalAmount, om.order_type AS orderType, om.status, om.is_draft AS isDraft, DATE_FORMAT(om.create_time, '%Y-%m-%d %H:%i:%s') AS createTime, wh.warehouseNames FROM order_master om LEFT JOIN shop s ON om.shop_id = s.id LEFT JOIN customer c ON om.customer_id = c.id LEFT JOIN ( SELECT os.master_id, GROUP_CONCAT(DISTINCT w.warehouse_name ORDER BY w.warehouse_name SEPARATOR ',') AS warehouseNames FROM order_sub os LEFT JOIN warehouse w ON os.warehouse_id = w.id AND w.is_delete = 0 WHERE os.is_delete = 0 GROUP BY os.master_id ) wh ON wh.master_id = om.id WHERE 1 = 1
AND om.order_no LIKE CONCAT('%', #{query.orderNo}, '%')
AND om.order_type = #{query.orderType}
AND om.status = #{query.status}
AND om.is_draft = #{query.isDraft}
ORDER BY om.create_time DESC
